    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address receiver, uint amount, bool shouldTry) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(shouldTry == true || shouldTry == false);
        uint balCBefore = address(c).balance;
        uint balRecvBefore = receiver == address(this) ? address(this).balance : receiver.balance;
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balCAfter = address(c).balance;
        uint balRecvAfter = receiver == address(this) ? address(this).balance : receiver.balance;

        assert(
            reverted ||
            (
                receiver != address(0) &&
                amount > 0 &&
                amount <= balCBefore &&
                balCAfter == balCBefore - amount &&
                balRecvAfter == balRecvBefore + amount
            )
        );
    }
